// Not strict at the top level, so that the directive of `declared` is observable.

function declared (value) {
  'use strict'
  return [this, value, arguments.length]
}

const arrow = value => value * 2

const named = function named (value) {
  return value
}

class Base {
  constructor (value) {
    this.value = value
  }
}

class Derived extends Base {
  constructor (value) {
    super(value)
    this.derived = true
  }

  method (value) {
    return this.value + value
  }
}

const object = {
  property (value) {
    return value
  },
}

async function asyncFunction (value) {
  await undefined
  return value
}

function * generator () {
  yield 1
}

function throws () {
  throw new Error('boom')
}

module.exports = { declared, arrow, named, Base, Derived, object, asyncFunction, generator, throws }
